(()=>{const tabs=[...document.querySelectorAll('[data-dock]')],panes=[...document.querySelectorAll('[data-pane]')];function open(name){tabs.forEach(e=>e.classList.toggle('active',e.dataset.dock===name));panes.forEach(e=>e.classList.toggle('hidden',e.dataset.pane!==name))}tabs.forEach(e=>e.onclick=()=>open(e.dataset.dock));document.addEventListener('click',e=>{const mat=e.target.closest('[data-mat]');if(mat&&window.__nightwatch.state.materials.length===2)open('forge')});let last='';function sync(){const s=window.__nightwatch.state;if(s){const key=s.phase+'-'+s.materials.length;if(key!==last){last=key;document.querySelector('#forgeBadge').textContent=s.materials.length+' / 2';document.querySelector('#dockStatus').textContent=s.phase==='battle'?'交战中 · 装备锁定':s.phase==='prepare'?'整备阶段 · 点击装备操作':'守夜记录';}}}setInterval(sync,180);sync()})();
